sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // Admins see everything with no filter
    if (gs.hasRole('x_783736_time_tr_0.admin')) {
        return;
    }

    var uid = gs.getUserID();
    var utils = new x_783736_time_tr_0.TimeTrackerUtils();

    // Senior Manager (e.g., Chris Henry): sees own entries + all child teams under DSRP (DPOS Team + ERP)
    if (gs.hasRole('x_783736_time_tr_0.sr_manager')) {
        var deptTeams = utils.getDepartmentChildTeamIds(uid);
        if (deptTeams.length > 0) {
            current.addEncodedQuery('employee=' + uid + '^ORteamIN' + deptTeams.join(','));
        } else {
            current.addQuery('employee', uid);
        }
        return;
    }

    // Team Manager (e.g., Adriana Diaconu): sees own entries + entries for their managed team (DPOS Team)
    if (gs.hasRole('x_783736_time_tr_0.manager')) {
        var myTeams = utils.getManagedTeamIds(uid);
        if (myTeams.length > 0) {
            current.addEncodedQuery('employee=' + uid + '^ORteamIN' + myTeams.join(','));
        } else {
            current.addQuery('employee', uid);
        }
        return;
    }

    // Standard Employee (e.g., Matt Kirby, Christian Smith): sees strictly their own entries
    current.addQuery('employee', uid);

})(current, previous);
